{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://tui-gamepigeon.dev/contracts/restaurant-arena-trace-v3.schema.json",
  "title": "Restaurant Arena native trace v3",
  "$comment": "Native Arena export. v1 staff roles and initial state; v3 trace preserves event payloads and adds ordered inputs and checkpoint hashes. Existing event stateHash fields fingerprint event payloads, not full world state. replay.inputs[].stateHash and replay.finalStateHash fingerprint the full gameplay checkpoint. Optional restaurantStateHash fields fingerprint RestaurantState alone for cross-engine parity.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "episodeId",
    "seed",
    "envVersion",
    "contractVersion",
    "runKind",
    "initialState",
    "events",
    "deletion",
    "replay",
    "terminal"
  ],
  "properties": {
    "version": {
      "const": "restaurant-arena-trace/v3"
    },
    "episodeId": {
      "$ref": "#/$defs/arenaId"
    },
    "sessionId": {
      "$ref": "#/$defs/arenaId",
      "description": "The one run this trace came from. episodeId names the scenario and repeats across runs on the same seed, so it cannot identify a session. Optional: exports written before this field remain valid."
    },
    "seed": {
      "type": "integer",
      "minimum": 0
    },
    "envVersion": {
      "type": "string",
      "minLength": 1
    },
    "contractVersion": {
      "const": "restaurant-arena/v1"
    },
    "runKind": {
      "$comment": "Live gameplay, synthetic episodes, and benchmark episodes must stay distinguishable.",
      "enum": [
        "live",
        "synthetic",
        "benchmark"
      ]
    },
    "initialState": {
      "$ref": "https://tui-gamepigeon.dev/contracts/restaurant-arena-state-v1.schema.json"
    },
    "events": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/traceEvent"
      }
    },
    "deletion": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "requestId",
        "status"
      ],
      "properties": {
        "requestId": {
          "oneOf": [
            {
              "$ref": "#/$defs/arenaId"
            },
            {
              "type": "null"
            }
          ]
        },
        "status": {
          "enum": [
            "retained",
            "requested",
            "deleted"
          ]
        }
      }
    },
    "terminal": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "tick",
        "reason"
      ],
      "properties": {
        "status": {
          "enum": [
            "active",
            "completed",
            "abandoned"
          ]
        },
        "tick": {
          "type": "integer",
          "minimum": 0
        },
        "reason": {
          "type": [
            "string",
            "null"
          ]
        }
      }
    },
    "replay": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "variation",
        "inputs",
        "finalStateHash"
      ],
      "properties": {
        "variation": {
          "enum": [
            "tutorial-shift",
            "dinner-rush",
            "quiet-tuesday",
            "saturday-night"
          ]
        },
        "inputs": {
          "type": "array",
          "items": {
            "oneOf": [
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind",
                  "tick",
                  "stateHash",
                  "action"
                ],
                "properties": {
                  "tick": {
                    "type": "integer",
                    "minimum": 0
                  },
                  "stateHash": {
                    "type": "string",
                    "pattern": "^sha256:[0-9a-f]{64}$"
                  },
                  "restaurantStateHash": {
                    "type": "string",
                    "pattern": "^sha256:[0-9a-f]{64}$"
                  },
                  "kind": {
                    "const": "step"
                  },
                  "action": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind",
                  "tick",
                  "stateHash"
                ],
                "properties": {
                  "tick": {
                    "type": "integer",
                    "minimum": 0
                  },
                  "stateHash": {
                    "type": "string",
                    "pattern": "^sha256:[0-9a-f]{64}$"
                  },
