  // exported byte stream does not depend on whether a restamp happened.
  return events.map((event) => ({
    ...event,
    timestamp: new Date(base + event.tick * TRACE_TICK_INTERVAL_MS).toISOString(),
  }));
}

function mergeAdditionalEvents(
  recorded: TraceV3Event[],
  additional: TraceV3Event[] | undefined,
): TraceV3Event[] {
  if (!additional?.length) return recorded;
  const stamped = additional.map((event) => ({ ...event, round: roundForTick(event.tick) }));
  // Stable by tick: a caller-supplied event lands after the engine's own
  // events on the tick it belongs to rather than jumping ahead of them.
  return [...recorded, ...stamped].sort((left, right) => left.tick - right.tick);
}

/**
 * Turn a running game into a complete `restaurant-arena-trace/v3` record.
 *
 * Everything replay needs comes from the engine itself — the tick-0 snapshot it
 * froze at reset, its event journal, and its ordered input journal with the
 * checkpoint hash each input produced. The options only name the run.
 */
export function captureArenaTrace(
  game: ArenaTraceSource,
  options: TraceCaptureOptions,
): RestaurantArenaTraceV3 {
  const state = game.state();
  const seed = state.seed;
  const events = mergeAdditionalEvents(
    options.events ?? restampEvents(game.getRecordedEvents(), options.startTime),
    options.additionalEvents,
  );
  return {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id ?? `dinner-rush-${seed}`,
    ...(options.sessionId !== undefined ? { sessionId: options.sessionId } : {}),
    seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: game.getInitialState(),
    events,
    replay: game.getReplayRecord(),
    // The whole terminal record, not just the status string: a replay that
    // reaches "completed" on the wrong tick has not reproduced the run.
    terminal: game.getTerminalStatus(),
    deletion: {
      requestId: options.deletion?.requestId ?? null,
      status: options.deletion?.status ?? "retained",
    },
  };
}

// ── Export ───────────────────────────────────────────────────────────────

/**
 * The trace as a single indented JSON document. Keys stay in capture order —
 * this is the wire format a reviewer reads, not the canonical byte string the
 * hashes are taken over, so `initialState` keeps the shape of the state
 * contract instead of being alphabetised.
 */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return serializeJson(trace, true, false) ?? "null";
}

/**
 * The trace as JSONL: one header line carrying everything but the journal,
 * then one line per event. Lets a consumer stream a long benchmark episode
 * without holding the whole record in memory.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return [header, ...events].map((line) => serializeJson(line, false, false) ?? "null").join("\n");
}

// ── Validation ───────────────────────────────────────────────────────────

export interface TraceValidationResult {
  valid: boolean;
  /** One entry per rejected field, path first, so a caller can point at the offender. */
  errors: string[];
}

const ARENA_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,129}$/;
const STATE_HASH = /^sha256:[0-9a-f]{64}$/;

const TRACE_EVENT_KINDS: readonly string[] = [
  "observation", "action", "player_correction", "message", "outcome", "inspection",
  "hold", "hold_cleared", "verification_request", "verification_response",
  "escalation", "handoff", "supply_order", "supply_delivered", "stockout",
];
const TRACE_ROLES: readonly string[] = ["host", "supply_lead", "chef", "server", "expediter"];
const CORRECTION_CATEGORIES: readonly string[] = ["safety", "priority", "quality", "pace"];
const SUBJECT_KINDS: readonly string[] = ["order", "ingredient", "equipment", "handoff"];
const REPLAY_VARIATIONS: readonly string[] = [
  "tutorial-shift", "dinner-rush", "quiet-tuesday", "saturday-night",
];
const RUN_KINDS: readonly string[] = ["live", "synthetic", "benchmark"];
const DELETION_STATUSES: readonly string[] = ["retained", "requested", "deleted"];
const TERMINAL_STATUSES: readonly string[] = ["active", "completed", "abandoned"];

const TRACE_EVENT_FIELDS: readonly string[] = [
  "tick", "round", "kind", "timestamp", "stateHash", "actorId", "role", "targetRole",
  "checkpointId", "model", "requestId", "idempotencyKey", "text", "observation", "action",
  "toolResult", "outcome", "correctionRationale", "correctionCategory",
  "changedDecisionEventId", "probeEventId", "subject", "payload",
];
const TRACE_FIELDS: readonly string[] = [
  "version", "episodeId", "sessionId", "seed", "envVersion", "contractVersion", "runKind",
  "initialState", "events", "deletion", "replay", "terminal",
];
const INPUT_FIELDS_BY_KIND: Readonly<Record<string, readonly string[]>> = {
  step: ["kind", "tick", "stateHash", "restaurantStateHash", "action"],
  time: ["kind", "tick", "stateHash", "restaurantStateHash"],
  envelope: ["kind", "tick", "stateHash", "restaurantStateHash", "envelope", "telemetry"],
  controllers: ["kind", "tick", "stateHash", "restaurantStateHash", "roles"],
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Field-by-field validation of a `restaurant-arena-trace/v3` record against
 * `contracts/restaurant-arena-trace-v3.schema.json`.
 *
 * Reports every offending field rather than stopping at the first, because the
 * common cause of a rejection is a producer that got a whole family of fields
 * wrong and one error at a time makes that take five runs to see. Structural
 * validation only: hash agreement is `replayArenaTrace`'s job.
 */
export function validateArenaTraceV3(value: unknown): TraceValidationResult {
  const errors: string[] = [];
  const push = (path: string, message: string) => void errors.push(`${path}: ${message}`);

  if (!isPlainObject(value)) return { valid: false, errors: ["trace: expected a JSON object"] };

  const requireInteger = (path: string, candidate: unknown, minimum: number): void => {
    if (typeof candidate !== "number" || !Number.isInteger(candidate) || candidate < minimum) {
      push(path, `expected an integer >= ${minimum}`);
    }
  };
  const requireArenaId = (path: string, candidate: unknown): void => {
    if (typeof candidate !== "string" || !ARENA_ID.test(candidate)) {
      push(path, "expected an arena id matching ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$");
    }
  };
  const requireStateHash = (path: string, candidate: unknown): void => {
    if (typeof candidate !== "string" || !STATE_HASH.test(candidate)) {
      push(path, "expected a hash matching ^sha256:[0-9a-f]{64}$");
    }
  };
  const requireEnum = (path: string, candidate: unknown, allowed: readonly string[]): void => {
    if (typeof candidate !== "string" || !allowed.includes(candidate)) {
      push(path, `expected one of ${allowed.join(", ")}`);
    }
  };
  const requireNullableObject = (path: string, candidate: unknown): void => {
    if (candidate !== null && !isPlainObject(candidate)) push(path, "expected an object or null");
  };
  const rejectUnknownFields = (path: string, record: Record<string, unknown>, allowed: readonly string[]): void => {
    for (const key of Object.keys(record)) {
      if (!allowed.includes(key)) push(`${path}${path ? "." : ""}${key}`, "unknown field");
    }
  };

  rejectUnknownFields("", value, TRACE_FIELDS);
  for (const required of ["version", "episodeId", "seed", "envVersion", "contractVersion", "runKind", "initialState", "events", "deletion", "replay", "terminal"]) {
    if (value[required] === undefined) push(required, "required field is missing");
  }

  if (value.version !== TRACE_V3_VERSION) push("version", `expected "${TRACE_V3_VERSION}"`);
  if (value.episodeId !== undefined) requireArenaId("episodeId", value.episodeId);
  // Optional, so pre-#281 exports stay valid — but an id that looks matchable
  // and is not is worse than none, so a malformed one is still rejected.
  if (value.sessionId !== undefined) requireArenaId("sessionId", value.sessionId);
  if (value.seed !== undefined) requireInteger("seed", value.seed, 0);
  if (value.envVersion !== undefined && (typeof value.envVersion !== "string" || value.envVersion.length === 0)) {
    push("envVersion", "expected a non-empty string");
  }
  if (value.contractVersion !== TRACE_V3_CONTRACT_VERSION) {
    push("contractVersion", `expected "${TRACE_V3_CONTRACT_VERSION}"`);
  }
  if (value.runKind !== undefined) requireEnum("runKind", value.runKind, RUN_KINDS);
  if (value.initialState !== undefined && !isRestaurantState(value.initialState)) {
    push("initialState", "does not satisfy restaurant-arena-state-v1");
  }

  if (value.events !== undefined && !Array.isArray(value.events)) {
    push("events", "expected an array");
  } else if (Array.isArray(value.events)) {
    value.events.forEach((event, index) => validateTraceEvent(`events[${index}]`, event, {
      push, requireInteger, requireArenaId, requireStateHash, requireEnum, requireNullableObject, rejectUnknownFields,
    }));
  }

  if (value.deletion !== undefined) {
    if (!isPlainObject(value.deletion)) {
      push("deletion", "expected an object");
    } else {
      rejectUnknownFields("deletion", value.deletion, ["requestId", "status"]);
      if (value.deletion.requestId === undefined) push("deletion.requestId", "required field is missing");
      else if (value.deletion.requestId !== null) requireArenaId("deletion.requestId", value.deletion.requestId);
      if (value.deletion.status === undefined) push("deletion.status", "required field is missing");
      else requireEnum("deletion.status", value.deletion.status, DELETION_STATUSES);
    }
  }

  if (value.terminal !== undefined) {
    if (!isPlainObject(value.terminal)) {
      push("terminal", "expected an object");
    } else {
      rejectUnknownFields("terminal", value.terminal, ["status", "tick", "reason"]);
      if (value.terminal.status === undefined) push("terminal.status", "required field is missing");
      else requireEnum("terminal.status", value.terminal.status, TERMINAL_STATUSES);
      if (value.terminal.tick === undefined) push("terminal.tick", "required field is missing");
      else requireInteger("terminal.tick", value.terminal.tick, 0);
      if (value.terminal.reason === undefined) push("terminal.reason", "required field is missing");
      else if (value.terminal.reason !== null && typeof value.terminal.reason !== "string") {
        push("terminal.reason", "expected a string or null");
      }
    }
  }

  if (value.replay !== undefined) {
    if (!isPlainObject(value.replay)) {
      push("replay", "expected an object");
    } else {
      const replay = value.replay;
      rejectUnknownFields("replay", replay, ["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"]);
      if (replay.variation === undefined) push("replay.variation", "required field is missing");
      else requireEnum("replay.variation", replay.variation, REPLAY_VARIATIONS);
      if (replay.finalStateHash === undefined) push("replay.finalStateHash", "required field is missing");
      else requireStateHash("replay.finalStateHash", replay.finalStateHash);
      if (replay.finalRestaurantStateHash !== undefined) {
        requireStateHash("replay.finalRestaurantStateHash", replay.finalRestaurantStateHash);
      }
      if (replay.inputs === undefined) push("replay.inputs", "required field is missing");
      else if (!Array.isArray(replay.inputs)) push("replay.inputs", "expected an array");
      else {
        replay.inputs.forEach((input, index) => {
          const path = `replay.inputs[${index}]`;
          if (!isPlainObject(input)) return void push(path, "expected an object");
          const allowed = typeof input.kind === "string" ? INPUT_FIELDS_BY_KIND[input.kind] : undefined;
          if (!allowed) {
            return void push(`${path}.kind`, `expected one of ${Object.keys(INPUT_FIELDS_BY_KIND).join(", ")}`);
          }
          rejectUnknownFields(path, input, allowed);
          requireInteger(`${path}.tick`, input.tick, 0);
          requireStateHash(`${path}.stateHash`, input.stateHash);
          if (input.restaurantStateHash !== undefined) {
            requireStateHash(`${path}.restaurantStateHash`, input.restaurantStateHash);
          }
          if (input.kind === "step" && (typeof input.action !== "string" || input.action.length === 0)) {
            push(`${path}.action`, "expected a non-empty action id");
          }
          if (input.kind === "envelope" && !isActionEnvelope(input.envelope)) {
            push(`${path}.envelope`, "does not satisfy restaurant-arena-action-v1");
          }
          if (input.kind === "envelope" && input.telemetry !== undefined && !isPlainObject(input.telemetry)) {
            push(`${path}.telemetry`, "expected an object");
          }
          if (input.kind === "controllers") {
            if (!Array.isArray(input.roles)) push(`${path}.roles`, "expected an array of roles");
            else {
              input.roles.forEach((role, roleIndex) => requireEnum(`${path}.roles[${roleIndex}]`, role, TRACE_ROLES));
              if (new Set(input.roles).size !== input.roles.length) push(`${path}.roles`, "expected unique roles");
            }
          }
        });
      }
    }
  }

  return { valid: errors.length === 0, errors };
}

/** The per-field checkers `validateArenaTraceV3` threads into the event pass. */
interface FieldCheckers {
  push(path: string, message: string): void;
  requireInteger(path: string, candidate: unknown, minimum: number): void;
  requireArenaId(path: string, candidate: unknown): void;
  requireStateHash(path: string, candidate: unknown): void;
  requireEnum(path: string, candidate: unknown, allowed: readonly string[]): void;
  requireNullableObject(path: string, candidate: unknown): void;
  rejectUnknownFields(path: string, record: Record<string, unknown>, allowed: readonly string[]): void;
}

function validateTraceEvent(path: string, event: unknown, check: FieldCheckers): void {
  if (!isPlainObject(event)) return void check.push(path, "expected an object");
  check.rejectUnknownFields(path, event, TRACE_EVENT_FIELDS);

  for (const required of ["tick", "kind", "timestamp", "stateHash"]) {
    if (event[required] === undefined) check.push(`${path}.${required}`, "required field is missing");
  }
  if (event.tick !== undefined) check.requireInteger(`${path}.tick`, event.tick, 0);
  if (event.round !== undefined) check.requireInteger(`${path}.round`, event.round, 1);
  if (event.kind !== undefined) check.requireEnum(`${path}.kind`, event.kind, TRACE_EVENT_KINDS);
  if (event.timestamp !== undefined && (typeof event.timestamp !== "string" || Number.isNaN(Date.parse(event.timestamp)))) {
    check.push(`${path}.timestamp`, "expected an RFC 3339 date-time");
  }
  if (event.stateHash !== undefined) check.requireStateHash(`${path}.stateHash`, event.stateHash);

  for (const field of ["actorId", "checkpointId", "requestId"] as const) {
    if (event[field] !== undefined) check.requireArenaId(`${path}.${field}`, event[field]);
  }
  for (const field of ["role", "targetRole"] as const) {
    if (event[field] !== undefined) check.requireEnum(`${path}.${field}`, event[field], TRACE_ROLES);
  }
  for (const field of ["changedDecisionEventId", "probeEventId"] as const) {
    if (event[field] !== undefined && event[field] !== null) check.requireArenaId(`${path}.${field}`, event[field]);
  }
  for (const field of ["text", "correctionRationale"] as const) {
    if (event[field] !== undefined && event[field] !== null && typeof event[field] !== "string") {
      check.push(`${path}.${field}`, "expected a string or null");
    }
  }
  for (const field of ["observation", "action", "outcome", "payload"] as const) {
    if (event[field] !== undefined) check.requireNullableObject(`${path}.${field}`, event[field]);
  }
  if (event.idempotencyKey !== undefined && (typeof event.idempotencyKey !== "string" || !IDEMPOTENCY_KEY.test(event.idempotencyKey))) {
    check.push(`${path}.idempotencyKey`, "expected an idempotency key matching ^[A-Za-z0-9][A-Za-z0-9._:-]{0,129}$");
  }
  if (event.correctionCategory !== undefined && event.correctionCategory !== null) {
    check.requireEnum(`${path}.correctionCategory`, event.correctionCategory, CORRECTION_CATEGORIES);
  }

  if (event.model !== undefined) {
    if (!isPlainObject(event.model)) {
      check.push(`${path}.model`, "expected an object");
    } else {
      check.rejectUnknownFields(`${path}.model`, event.model, ["provider", "name", "version"]);
      for (const field of ["provider", "name"] as const) {
        if (typeof event.model[field] !== "string" || event.model[field] === "") {
          check.push(`${path}.model.${field}`, "expected a non-empty string");
        }
      }
      if (event.model.version !== undefined && (typeof event.model.version !== "string" || event.model.version === "")) {
        check.push(`${path}.model.version`, "expected a non-empty string");
      }
    }
  }

  if (event.subject !== undefined) {
    if (!isPlainObject(event.subject)) {
      check.push(`${path}.subject`, "expected an object");
    } else {
      check.rejectUnknownFields(`${path}.subject`, event.subject, ["kind", "id"]);
      check.requireEnum(`${path}.subject.kind`, event.subject.kind, SUBJECT_KINDS);
      check.requireArenaId(`${path}.subject.id`, event.subject.id);
    }
  }

  if (event.toolResult !== undefined && event.toolResult !== null) {
    if (!isPlainObject(event.toolResult)) {
      check.push(`${path}.toolResult`, "expected an object or null");
    } else {
      const result = event.toolResult;
      if (result.ok !== undefined && typeof result.ok !== "boolean") {
        check.push(`${path}.toolResult.ok`, "expected a boolean");
      }
      if (result.latencyMs !== undefined && (typeof result.latencyMs !== "number" || result.latencyMs < 0)) {
        check.push(`${path}.toolResult.latencyMs`, "expected a number >= 0");
      }
      const failed = result.ok === false;
      const hasError = isPlainObject(result.error);
      // The two halves must agree: a consumer filtering on `ok` and one
      // filtering on error presence must not disagree about the same event.
      if (failed && !hasError) check.push(`${path}.toolResult.error`, "a failed call must carry its error body");
      if (hasError && !failed) check.push(`${path}.toolResult.ok`, "an error body means the call failed, so ok must be false");
      if (hasError) {
        const error = result.error as Record<string, unknown>;
        for (const field of ["code", "message"] as const) {
          if (typeof error[field] !== "string" || error[field] === "") {
            check.push(`${path}.toolResult.error.${field}`, "expected a non-empty string");
          }
        }
        if (error.retryable !== undefined && typeof error.retryable !== "boolean") {
          check.push(`${path}.toolResult.error.retryable`, "expected a boolean");
        }
      } else if (result.error !== undefined && result.error !== null) {
        check.push(`${path}.toolResult.error`, "expected an object or null");
      }
    }
  }
}

