/**
 * Native replay of a `restaurant-arena-trace/v3` record.
 *
 * Replay is the only thing that makes a trace a claim rather than a story: the
 * record says "these inputs, from this seed, produced this world", and the way
 * to test that is to run the real engine over the recorded inputs and compare
 * every checkpoint it produces against the ones the record carries. Nothing
 * here trusts a hash it was handed — each one is recomputed from the live game.
 */

import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";
import type { Role } from "./types.js";

/**
 * Apply one recorded input to a live game, through the same public entry point
 * the original run went through. No hash checking: the overlay uses this to
 * animate a saved run, and `replayArenaTrace` layers the verification on top.
 */
export function applyArenaReplayInput(
  game: RestaurantGame,
  input: ArenaInputRecord,
  index: number,
): void {
  switch (input.kind) {
    case "step":
      game.step(input.action as RestaurantGameAction);
      return;
    case "time":
      game.advanceTime();
      return;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      return;
    case "controllers":
      game.setExternalControllers(input.roles as readonly (Role | "expediter")[]);
      return;
    default:
      throw new Error(`replay input ${index}: unknown input kind ${JSON.stringify((input as { kind: unknown }).kind)}`);
  }
}

/**
