/**
 * Export (or check) the benchmark Restaurant Arena trace fixture.
 *
 *   bun scripts/export-arena-trace.ts           # write contracts/fixtures/restaurant-arena-trace-v3.json
 *   bun scripts/export-arena-trace.ts --check   # fail if the fixture on disk is not what a fresh capture produces
 *
 * The fixture is a scripted shift, not a recording: the same actions in the
 * same order from the same seed, timestamped from a fixed `startTime`. That is
 * what makes `--check` meaningful — any difference is an engine change, never
 * the time of day the export ran.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import { exportTraceJson, validateArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

const ROOT = resolve(import.meta.dir, "..");
const FIXTURE_PATH = resolve(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

/** The fixture episode: Dinner Rush on the frozen benchmark seed. */
const FIXTURE_SEED = 218220;
const FIXTURE_VARIATION = "dinner-rush";
const FIXTURE_EPISODE_ID = "dinner-rush-benchmark-218220";
/** Frozen wall clock, so the export is reproducible byte for byte. */
const FIXTURE_START_TIME = "2026-09-05T18:00:00.000Z";

function captureFixtureTrace() {
  const game = new RestaurantGame(FIXTURE_SEED, FIXTURE_VARIATION);
  game.step("sim_start");
  // Ten ticks to the oven failure and the unverified substitution, the manager's
  // safety correction, then the rest of the shift so the record runs to
  // completion — the warming-shelf probe at tick 15 and the outcome at 24.
  for (let tick = 0; tick < 10; tick++) game.step("tick");
  game.step("verify_substitution");
  for (let tick = 0; tick < 14; tick++) game.step("tick");
  return game.captureTrace({
    runKind: "benchmark",
    episodeId: FIXTURE_EPISODE_ID,
    startTime: FIXTURE_START_TIME,
  });
}

const check = process.argv.slice(2).includes("--check");
const trace = captureFixtureTrace();

const validation = validateArenaTraceV3(trace);
if (!validation.valid) {
  console.error(`Captured fixture trace is not schema-valid:\n${validation.errors.map((error) => `  ${error}`).join("\n")}`);
  process.exit(1);
}
// A fixture that cannot be replayed is worse than no fixture: every consumer
// downstream would inherit the broken claim.
replayArenaTrace(trace);

const contents = `${exportTraceJson(trace)}\n`;
const displayPath = relative(ROOT, FIXTURE_PATH);

if (check) {
  let onDisk: string;
  try {
    onDisk = readFileSync(FIXTURE_PATH, "utf8");
  } catch (error) {
    console.error(`Fixture is missing at ${displayPath}: ${String(error)}`);
    process.exit(1);
  }
  if (onDisk !== contents) {
    console.error(`Fixture is stale at ${displayPath}. Run: bun scripts/export-arena-trace.ts`);
    process.exit(1);
  }
  console.log(`Fixture is current: ${displayPath} (${trace.events.length} events, ${trace.replay.inputs.length} inputs)`);
} else {
  writeFileSync(FIXTURE_PATH, contents);
  console.log(`Wrote ${displayPath} (${trace.events.length} events, ${trace.replay.inputs.length} inputs)`);
}

