 * Natively replay a Restaurant Arena trace file and report whether it holds up.
 *
 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
 *
 * Accepts either export format. Prints `Native replay passed` and exits 0 only
 * when the record is schema-valid *and* the real engine reproduces every
 * checkpoint, both final hashes, and the whole terminal record from the seed.
 * Anything else — a tampered hash, a truncated journal, an edited outcome — is
 * a non-zero exit with the reason.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { validateArenaTraceV3, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
