import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "./restaurant-game.js";
import { roundForTick } from "./rounds.js";
import {
  ARENA_ENV_VERSION,
  TRACE_V3_CONTRACT_VERSION,
  TRACE_V3_VERSION,
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

const FIXTURE_PATH = join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json");

/** A shift played to completion, so the trace carries a terminal record. */
function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed);
  game.step("sim_start");
  for (let tick = 0; tick < 10; tick++) game.step("tick");
  game.step("verify_substitution");
  for (let tick = 0; tick < 14; tick++) game.step("tick");
  return game;
}

function fixtureTrace(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE_PATH, "utf8")) as RestaurantArenaTraceV3;
}

describe("capturing a restaurant-arena-trace-v3 record (#275)", () => {
  it("captures tick-0 state, the event journal and the replay inputs from a running game", () => {
    const game = playedShift();
    const trace = game.captureTrace({ runKind: "benchmark" });

    expect(trace.version).toBe(TRACE_V3_VERSION);
    expect(trace.contractVersion).toBe(TRACE_V3_CONTRACT_VERSION);
    expect(trace.envVersion).toBe(ARENA_ENV_VERSION);
    expect(trace.runKind).toBe("benchmark");
    expect(trace.seed).toBe(218220);
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });

    // Tick 0, not the world as it stands now: the shift ran to completion.
    expect((trace.initialState as { episode: { tick: number } }).episode.tick).toBe(0);
    expect(trace.terminal).toEqual({ status: "completed", tick: 24, reason: "episode_complete" });
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("captures the whole terminal record, not just the status string", () => {
    const trace = new RestaurantGame(218220).captureTrace({ runKind: "live" });
    expect(trace.terminal).toEqual({ status: "active", tick: 0, reason: null });
  });

  it("is available as an instance method and a standalone helper with the same options", () => {
    const game = playedShift();
    const options = { runKind: "synthetic", episodeId: "synthetic-218220" } as const;
    expect(game.captureTrace(options)).toEqual(captureArenaTrace(game, options));
  });

  it("names the run: episodeId defaults to the scenario, sessionId is opt-in (#281)", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "live" }).episodeId).toBe("dinner-rush-001");
    expect(game.captureTrace({ runKind: "live" }).sessionId).toBeUndefined();

    // Two runs of one scenario stay distinguishable only through sessionId.
    const first = game.captureTrace({ runKind: "live", sessionId: "game_aaa" });
    const second = game.captureTrace({ runKind: "live", sessionId: "game_bbb" });
    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).not.toBe(second.sessionId);
    expect(validateArenaTraceV3(first).valid).toBe(true);
  });

  it("derives event timestamps from startTime so a scripted capture is reproducible", () => {
    const trace = playedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });
    expect(trace.events[0]!.timestamp).toBe("2026-09-05T18:00:00.000Z");
    expect(trace.events.at(-1)!.timestamp).toBe("2026-09-05T18:01:12.000Z"); // tick 24 × 3s
    expect(() => playedShift().captureTrace({ runKind: "live", startTime: "not a date" })).toThrow(/startTime/);
  });

  it("merges additionalEvents into the journal and stamps each with the round its tick falls in", () => {
    const game = playedShift();
    const note: TraceV3Event = {
      tick: 9,
      kind: "message",
      timestamp: "2026-09-05T18:00:27.000Z",
      stateHash: `sha256:${"a".repeat(64)}`,
      actorId: "player",
      text: "out-of-band player note",
    };
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note, { ...note, tick: 0, round: 99 }] });

    expect(trace.events.length).toBe(game.getRecordedEvents().length + 2);
    expect(trace.events.map(({ tick }) => tick)).toEqual([...trace.events].map(({ tick }) => tick).sort((a, b) => a - b));
    // roundForTick wins over whatever the caller claimed: round 5 covers ticks
    // 9 and 10, and tick 0 is round 1.
    const merged = trace.events.filter((event) => event.text === "out-of-band player note");
    expect(merged.map(({ tick, round }) => [tick, round])).toEqual([[0, roundForTick(0)], [9, roundForTick(9)]]);
    expect(validateArenaTraceV3(trace).valid).toBe(true);
  });

  it("replaces the journal wholesale when events is passed", () => {
    const trace = playedShift().captureTrace({ runKind: "synthetic", events: [] });
    expect(trace.events).toEqual([]);
  });
});

describe("exporting a restaurant-arena-trace-v3 record", () => {
  it("writes indented JSON that round-trips and matches the checked-in fixture", () => {
    const json = exportTraceJson(fixtureTrace());
    expect(json.split("\n").length).toBeGreaterThan(1);
    expect(`${json}\n`).toBe(readFileSync(FIXTURE_PATH, "utf8"));
    expect(validateArenaTraceV3(JSON.parse(json)).valid).toBe(true);
  });

  it("writes JSONL as one header line plus one line per event", () => {
    const trace = fixtureTrace();
    const lines = exportTraceJsonl(trace).split("\n");

    expect(lines.length).toBe(trace.events.length + 1);
    const header = JSON.parse(lines[0]!) as Record<string, unknown>;
    expect(header.events).toBeUndefined();
    expect(header).toMatchObject({ version: trace.version, replay: trace.replay });
    // Rejoining the two halves is the whole point: it must validate again.
    const rejoined = { ...header, events: lines.slice(1).map((line) => JSON.parse(line)) };
    expect(validateArenaTraceV3(rejoined)).toEqual({ valid: true, errors: [] });
  });
});

describe("validating a restaurant-arena-trace-v3 record field by field", () => {
  it("accepts the fixture and a freshly captured live trace", () => {
    expect(validateArenaTraceV3(fixtureTrace())).toEqual({ valid: true, errors: [] });
    expect(validateArenaTraceV3(playedShift().captureTrace({ runKind: "live" }))).toEqual({ valid: true, errors: [] });
  });

  it("rejects a non-object", () => {
    for (const value of [null, 7, "trace", [fixtureTrace()]]) {
      expect(validateArenaTraceV3(value).valid).toBe(false);
    }
  });

  it("names the offending field, one error per malformed field", () => {
    const cases: [string, (trace: Record<string, unknown>) => void][] = [
      ["version", (trace) => void (trace.version = "restaurant-arena-trace/v2")],
      ["contractVersion", (trace) => void (trace.contractVersion = "restaurant-arena/v2")],
      ["episodeId", (trace) => void (trace.episodeId = "not a valid id!")],
      ["sessionId", (trace) => void (trace.sessionId = "")],
      ["seed", (trace) => void (trace.seed = -1)],
      ["envVersion", (trace) => void (trace.envVersion = "")],
      ["runKind", (trace) => void (trace.runKind = "practice")],
      ["initialState", (trace) => void ((trace.initialState as { reputation: number }).reputation = 500)],
      ["events", (trace) => void (trace.events = {})],
      ["events[0].kind", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.kind = "gossip")],
      ["events[0].stateHash", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.stateHash = "sha256:beef")],
      ["events[0].timestamp", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.timestamp = "yesterday")],
      ["events[0].round", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.round = 0)],
      ["events[0].role", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.role = "sommelier")],
      ["events[0].sauce", (trace) => void ((trace.events as Record<string, unknown>[])[0]!.sauce = "extra")],
      ["deletion.status", (trace) => void ((trace.deletion as Record<string, unknown>).status = "shredded")],
      ["deletion.requestId", (trace) => void ((trace.deletion as Record<string, unknown>).requestId = 12)],
      ["terminal.status", (trace) => void ((trace.terminal as Record<string, unknown>).status = "cancelled")],
      ["terminal.tick", (trace) => void ((trace.terminal as Record<string, unknown>).tick = 1.5)],
      ["terminal.reason", (trace) => void ((trace.terminal as Record<string, unknown>).reason = 42)],
      ["replay.variation", (trace) => void ((trace.replay as Record<string, unknown>).variation = "brunch")],
      ["replay.finalStateHash", (trace) => void ((trace.replay as Record<string, unknown>).finalStateHash = "beef")],
      ["replay.inputs", (trace) => void ((trace.replay as Record<string, unknown>).inputs = "step")],
      ["replay.inputs[0].kind", (trace) => void (((trace.replay as { inputs: Record<string, unknown>[] }).inputs[0]!.kind = "teleport"))],
      ["replay.inputs[0].action", (trace) => void (((trace.replay as { inputs: Record<string, unknown>[] }).inputs[0]!.action = ""))],
      ["replay.inputs[0].stateHash", (trace) => void (((trace.replay as { inputs: Record<string, unknown>[] }).inputs[0]!.stateHash = "sha256:BEEF"))],
      ["sauce", (trace) => void (trace.sauce = "extra")],
    ];

    for (const [field, tamper] of cases) {
      const trace = fixtureTrace() as unknown as Record<string, unknown>;
      tamper(trace);
      const result = validateArenaTraceV3(trace);
      expect(result.valid).toBe(false);
      expect(result.errors.some((error) => error.startsWith(`${field}:`))).toBe(true);
    }
  });

  it("rejects a record missing any required field, naming it", () => {
    for (const field of ["version", "episodeId", "seed", "envVersion", "contractVersion", "runKind", "initialState", "events", "deletion", "replay", "terminal"]) {
      const trace = fixtureTrace() as unknown as Record<string, unknown>;
      delete trace[field];
      const result = validateArenaTraceV3(trace);
      expect(result.valid).toBe(false);
      expect(result.errors.some((error) => error.startsWith(`${field}:`))).toBe(true);
    }
  });

  it("keeps `ok` and `error` in a toolResult from disagreeing about the same event", () => {
    const withResult = (toolResult: Record<string, unknown>) => {
      const trace = fixtureTrace();
      trace.events[1]!.toolResult = toolResult;
      return validateArenaTraceV3(trace);
    };
    expect(withResult({ ok: true, status: "verified" }).valid).toBe(true);
    expect(withResult({ ok: false, error: { code: "rejected", message: "no" } }).valid).toBe(true);
    expect(withResult({ ok: false }).errors).toContain("events[1].toolResult.error: a failed call must carry its error body");
    expect(withResult({ ok: true, error: { code: "rejected", message: "no" } }).errors)
      .toContain("events[1].toolResult.ok: an error body means the call failed, so ok must be false");
  });

  it("reports every malformed field at once rather than stopping at the first", () => {
    const trace = fixtureTrace() as unknown as Record<string, unknown>;
    trace.runKind = "practice";
    trace.seed = -3;
    const result = validateArenaTraceV3(trace);
    expect(result.errors.length).toBe(2);
  });
});

