import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { applyArenaReplayInput, replayArenaTrace } from "./replay.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";
import type { ActionEnvelope } from "./types.js";

function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed);
  game.step("sim_start");
  for (let tick = 0; tick < 10; tick++) game.step("tick");
  game.step("verify_substitution");
  for (let tick = 0; tick < 14; tick++) game.step("tick");
  return game;
}

function capturedShift(): RestaurantArenaTraceV3 {
  return playedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });
}

describe("replaying a restaurant-arena-trace-v3 record natively (#275)", () => {
  it("returns the rebuilt game itself, not a summary", () => {
    const trace = capturedShift();
    const game = replayArenaTrace(trace);

    expect(game).toBeInstanceOf(RestaurantGame);
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
    expect(game.state()).toEqual(playedShift().state());
  });

  it("replays a trace captured from a run driven through envelopes and controllers", () => {
    const game = new RestaurantGame(218220);
    game.setExternalControllers(["chef"]);
    game.step("sim_start");
    game.advanceTime();
    const envelope: ActionEnvelope = {
      version: "restaurant-arena-action/v1",
      episodeId: game.state().episode.id,
      actorId: "worker-chef",
      actorType: "worker",
      role: "chef",
      tool: "prepare",
      arguments: { orderId: "order-1" },
      tick: game.state().episode.tick,
      timestamp: "2026-09-05T18:00:03.000Z",
      requestId: "req-prepare-1",
      idempotencyKey: "dinner-rush-001:req-prepare-1",
    };
    game.stepEnvelope(envelope, { latencyMs: 42 });
    for (let tick = 0; tick < 23; tick++) game.step("tick");

    const trace = game.captureTrace({ runKind: "live" });
    expect(trace.replay.inputs.map(({ kind }) => kind)).toContain("controllers");
    expect(trace.replay.inputs.map(({ kind }) => kind)).toContain("envelope");
    expect(trace.replay.inputs.map(({ kind }) => kind)).toContain("time");
    expect(replayArenaTrace(trace).getTerminalStatus()).toEqual(trace.terminal);
  });

  it("starts from the engine's own tick-0 world and rejects an altered initialState", () => {
    // `cash` has no dedicated schema rule and still parses — but it is no
    // longer what this seed produces at tick 0, so replay must not proceed.
    const trace = capturedShift();
    (trace.initialState as { outcomes: { cash: number } }).outcomes.cash = 12;
    expect(() => replayArenaTrace(trace)).toThrow(/initial state mismatch/);

    const reseated = capturedShift();
