import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { copyFileSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
const SCRIPT = join(ROOT, "scripts/export-arena-trace.ts");
const FIXTURE = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

function run(...args: string[]) {
  return spawnSync("bun", [SCRIPT, ...args], { cwd: ROOT, encoding: "utf8" });
}

describe("scripts/export-arena-trace.ts", () => {
  test("--check reports the checked-in fixture as current", () => {
    const result = run("--check");
    expect(result.stdout).toContain("Fixture is current");
    expect(result.status).toBe(0);
  });

  test("writes the fixture and says so", () => {
    const before = readFileSync(FIXTURE, "utf8");
    const result = run();
    expect(result.stdout).toContain("Wrote");
    expect(result.stdout).toContain("contracts/fixtures/restaurant-arena-trace-v3.json");
    expect(result.status).toBe(0);
    // Reproducible: a second export of the same scripted shift is byte-identical.
    expect(readFileSync(FIXTURE, "utf8")).toBe(before);
  });

  test("--check fails without rewriting a stale fixture", () => {
    const backup = `${FIXTURE}.bak`;
    copyFileSync(FIXTURE, backup);
    try {
      const stale = JSON.parse(readFileSync(FIXTURE, "utf8")) as { seed: number };
      stale.seed = 1;
      writeFileSync(FIXTURE, `${JSON.stringify(stale, null, 2)}\n`);

      const result = run("--check");
      expect(result.status).not.toBe(0);
      expect(result.stdout).not.toContain("Fixture is current");
      expect(readFileSync(FIXTURE, "utf8")).not.toBe(readFileSync(backup, "utf8"));
    } finally {
      copyFileSync(backup, FIXTURE);
      spawnSync("rm", ["-f", backup]);
    }
  });
});

