import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { exportTraceJsonl } from "../src/games/restaurant-arena/trace.js";
import type { RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";

const ROOT = join(import.meta.dir, "..");
const SCRIPT = join(ROOT, "scripts/replay-arena-trace.ts");
const FIXTURE = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");
const WORK = mkdtempSync(join(tmpdir(), "arena-replay-"));

function run(path: string) {
  return spawnSync("bun", [SCRIPT, path], { cwd: ROOT, encoding: "utf8" });
}

function fixture(): RestaurantArenaTraceV3 {
  return JSON.parse(readFileSync(FIXTURE, "utf8")) as RestaurantArenaTraceV3;
}

/** Write a variant of the fixture and replay it. */
function replayVariant(name: string, mutate: (trace: RestaurantArenaTraceV3) => void) {
  const trace = fixture();
  mutate(trace);
  const path = join(WORK, name);
  writeFileSync(path, `${JSON.stringify(trace, null, 2)}\n`);
  return run(path);
}

describe("scripts/replay-arena-trace.ts", () => {
  test("passes on the benchmark fixture JSON", () => {
    const result = run(FIXTURE);
    expect(result.stdout).toContain("Native replay passed");
    expect(result.status).toBe(0);
  });

  test("passes on the JSONL export of the same trace", () => {
    const path = join(WORK, "fixture.jsonl");
    writeFileSync(path, exportTraceJsonl(fixture()));
    const result = run(path);
    expect(result.stdout).toContain("Native replay passed");
    expect(result.status).toBe(0);
  });

  test("fails on a tampered checkpoint hash", () => {
    const result = replayVariant("tampered.json", (trace) => {
      trace.replay.inputs[4]!.stateHash = `sha256:${"0".repeat(64)}`;
    });
    expect(result.stdout).not.toContain("Native replay passed");
    expect(result.status).not.toBe(0);
  });

  test("fails on a truncated input journal", () => {
    const result = replayVariant("truncated.json", (trace) => {
      trace.replay.inputs = trace.replay.inputs.slice(0, -4);
    });
    expect(result.stdout).not.toContain("Native replay passed");
    expect(result.status).not.toBe(0);
  });

  test("fails on an edited terminal reason alone", () => {
    const result = replayVariant("reason.json", (trace) => {
      trace.terminal = { ...trace.terminal, reason: "user_quit" };
    });
    expect(result.stdout).not.toContain("Native replay passed");
    expect(result.status).not.toBe(0);
  });

  test("fails a schema-invalid record before attempting replay", () => {
    const result = replayVariant("invalid.json", (trace) => {
      (trace as unknown as Record<string, unknown>).runKind = "practice";
    });
    expect(result.stderr).toContain("Schema validation failed");
    expect(result.stdout).not.toContain("Native replay passed");
    expect(result.status).not.toBe(0);
  });

  test("fails on a file that is not a trace at all", () => {
    const path = join(WORK, "garbage.json");
    writeFileSync(path, "{ not json");
    const result = run(path);
    expect(result.stdout).not.toContain("Native replay passed");
    expect(result.status).not.toBe(0);
  });
});

